const niches = [
  { pillar: 'why business needs a mobile app', platform: 'mobile', category: 'Mobile Development' },
  { pillar: 'why restaurants need an ordering app', platform: 'android', category: 'Mobile Development' },
  { pillar: 'why service businesses need an iPhone app', platform: 'ios', category: 'Mobile Development' },
  { pillar: 'app vs WhatsApp Business for customer orders', platform: 'mobile', category: 'Mobile Development' },
  { pillar: 'why clinics need a patient app', platform: 'ios', category: 'Mobile Development' },
  { pillar: 'why field sales teams need an Android app', platform: 'android', category: 'Mobile Development' },
  { pillar: 'why schools need a parent communication app', platform: 'mobile', category: 'Mobile Development' },
  { pillar: 'custom app vs no-code app for growing SMEs', platform: 'mobile', category: 'Mobile Development' },
  { pillar: 'why ecommerce brands need an iOS shopping app', platform: 'ios', category: 'Mobile Development' },
  { pillar: 'why local businesses in India need Android apps', platform: 'android', category: 'Mobile Development' },
  { pillar: 'website vs mobile app which first for startups', platform: 'web', category: 'Web Development' },
  { pillar: 'why logistics companies need a driver app', platform: 'android', category: 'Mobile Development' },
];

const day = new Date().getUTCDate();
const niche = niches[day % niches.length];
const today = new Date().toISOString().slice(0, 10);

return [{ json: { ...niche, today } }];

const niche = $('Pick Business Niche').item.json;
const file = $json;
const sha = file.sha;
const decoded = Buffer.from(file.content.replace(/\n/g, ''), 'base64').toString('utf8');
const blogs = JSON.parse(decoded);
const usedSlugs = blogs.map((b) => b.slug);
const usedImages = blogs.map((b) => b.image).filter(Boolean);
const usedPhotoIds = usedImages.map((u) => String(u).match(/photo-([a-zA-Z0-9_-]+)/)?.[1]).filter(Boolean);
const existingTitles = blogs.map((b) => b.title);
const existingKeywords = blogs.flatMap((b) => [b.title, ...(b.tags || [])]).join(' | ');

return [{
  json: {
    ...niche,
    sha,
    blogsJson: decoded,
    usedSlugs,
    usedImages,
    usedPhotoIds,
    existingTitles: existingTitles.slice(-20).join(' | '),
    existingKeywords: existingKeywords.slice(0, 1500),
    nextId: Math.max(0, ...blogs.map((b) => Number(b.id) || 0)) + 1,
  }
}];

const ctx = $json;
// Keyword often burns Gemini/auto pools — prefer high-quota GLM/Gemma for the long blog call.
return [{
  json: {
    ...ctx,
    keywordModel: 'auto:fast',
    keywordModelAlt: 'auto',
    blogModel: 'glm-4.7-flash',
    blogModelAlt: 'gemma-4-26b',
    expandModel: 'glm-4.7-flash',
  }
}];

