const ctx = $('Set FreeLLM auto models').item.json;
const raw = $json.choices?.[0]?.message?.content || '';
if (!raw) throw new Error('Keyword Agent empty after primary + fallback. Wait ~2 min or Clear cooldowns in FreeLLMUI.');
let kw;
try {
  kw = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Keyword Agent did not return JSON');
  kw = JSON.parse(m[0]);
}

const primaryKeyword = String(kw.primaryKeyword || '').trim().toLowerCase();
if (!primaryKeyword || primaryKeyword.split(/\s+/).length < 3) {
  throw new Error('primaryKeyword must be a long-tail phrase (3+ words): ' + primaryKeyword);
}

const bannedHeads = ['app development', 'android app', 'ios app', 'mobile app', 'web development'];
if (bannedHeads.includes(primaryKeyword)) {
  throw new Error('primaryKeyword too competitive/generic: ' + primaryKeyword);
}

const seed = kw.seed || kw.blogAngle || primaryKeyword;
const secondaryKeywords = Array.isArray(kw.secondaryKeywords) ? kw.secondaryKeywords : [];
const tags = Array.isArray(kw.tags) && kw.tags.length ? kw.tags : ['Mobile', 'Business', 'Apps'];
const usedModel = $json.model || ctx.keywordModel;

return [{
  json: {
    ...ctx,
    keywordModel: usedModel,
    primaryKeyword,
    secondaryKeywords,
    searchIntent: kw.searchIntent || 'commercial',
    competition: kw.competition || 'low',
    whyLowCompetition: kw.whyLowCompetition || '',
    blogAngle: kw.blogAngle || '',
    seed,
    category: kw.category || ctx.category,
    tags,
    unsplashQuery: kw.unsplashQuery || 'small business owner smartphone',
    query: primaryKeyword,
  }
}];

const topic = $('Parse Keyword Agent').item.json;
const ddg = $json || {};
const bits = [];
if (ddg.AbstractText) bits.push(ddg.AbstractText);
if (Array.isArray(ddg.RelatedTopics)) {
  for (const t of ddg.RelatedTopics.slice(0, 8)) {
    if (t.Text) bits.push(t.Text);
    if (Array.isArray(t.Topics)) {
      for (const x of t.Topics.slice(0, 3)) if (x.Text) bits.push(x.Text);
    }
  }
}
const researchNotes = bits.length
  ? bits.slice(0, 12).map((b) => '- ' + b).join('\n')
  : '- Write from original business/product experience; do not copy web text.';

return [{ json: { ...topic, researchNotes } }];

