const ctx = $('Pack Research').item.json;
const choice = $json.choices?.[0] || {};
const finish = choice.finish_reason || '';
const raw = choice.message?.content || '';
if (!raw) throw new Error('Blog empty. Clear FreeLLM cooldowns and re-run Generate Blog.');
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Blog JSON parse failed');
  parsed = JSON.parse(m[0]);
}

function slugify(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-').replace(/-+/g, '-').slice(0, 90);
}

const title = (parsed.title || ctx.seed).trim();
let slug = slugify(title);
if (ctx.usedSlugs.includes(slug)) slug = `${slug}-${ctx.today.replace(/-/g, '')}`;

const content = String(parsed.content || parsed.body || parsed.post || '').trim();
const words = content.split(/\s+/).filter(Boolean).length;
if (words < 400) {
  throw new Error(`Draft too thin: ${words} words (model=${$json.model || ctx.blogModel}, finish=${finish}).`);
}

return [{
  json: {
    ...ctx,
    blogModel: $json.model || ctx.blogModel,
    title,
    slug,
    excerpt: parsed.excerpt || title,
    content,
    category: parsed.category || ctx.category,
    tags: Array.isArray(parsed.tags) && parsed.tags.length ? parsed.tags : ctx.tags,
    unsplashQuery: parsed.unsplashQuery || ctx.unsplashQuery,
    wordCount: words,
    needsExpand: words < 1200,
    author: 'Dhinova Team',
    date: ctx.today,
  }
}];

