const ctx = $('Parse Draft').item.json;
const raw = $json.choices?.[0]?.message?.content || '';
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Expand JSON parse failed');
  parsed = JSON.parse(m[0]);
}
const content = String(parsed.content || '').trim();
const words = content.split(/\s+/).filter(Boolean).length;
if (words < 1200) throw new Error(`Expand still short: ${words} words (model=${$json.model || ctx.expandModel})`);
const linkCount = (content.match(/https:\/\/dhinova\.com\//g) || []).length;
if (linkCount < 3) throw new Error(`Need 3+ internal links after expand, found ${linkCount}`);
return [{
  json: {
    ...ctx,
    blogModel: ($json.model || ctx.blogModel) + '+expand',
    title: (parsed.title || ctx.title).trim(),
    excerpt: parsed.excerpt || ctx.excerpt,
    content,
    category: parsed.category || ctx.category,
    tags: Array.isArray(parsed.tags) && parsed.tags.length ? parsed.tags : ctx.tags,
    unsplashQuery: parsed.unsplashQuery || ctx.unsplashQuery,
    wordCount: words,
    needsExpand: false,
  }
}];

const blog = $json;
if (blog.needsExpand) throw new Error('Blog still marked needsExpand');
const words = blog.wordCount || String(blog.content || '').split(/\s+/).filter(Boolean).length;
if (words < 1200) throw new Error(`Final gate: too short (${words})`);
const linkCount = (String(blog.content).match(/https:\/\/dhinova\.com\//g) || []).length;
if (linkCount < 3) throw new Error(`Final gate: need 3+ links, found ${linkCount}`);
const hay = (blog.title + ' ' + String(blog.content).slice(0, 800)).toLowerCase();
const tokens = String(blog.primaryKeyword || '').toLowerCase().split(/\s+/).filter((w) => w.length > 3);
const hit = tokens.filter((t) => hay.includes(t)).length;
if (tokens.length && hit < Math.ceil(tokens.length * 0.6)) {
  throw new Error('Final gate: primary keyword weak in title/intro');
}
return [{ json: { ...blog, wordCount: words, needsExpand: false } }];

const blog = $('Final Quality Gate').item.json;
const used = new Set(blog.usedPhotoIds || []);
const results = Array.isArray($json.results) ? $json.results : [];

let chosen = null;
for (const photo of results) {
  const id = photo?.id;
  if (!id) continue;
  if (used.has(id)) continue;
  if ((blog.usedImages || []).some((u) => String(u).includes(id))) continue;
  chosen = photo;
  break;
}
if (!chosen?.urls?.regular) throw new Error('No unused Unsplash image');

return [{ json: { ...blog, image: `${chosen.urls.regular}&w=1600&q=85`, unsplashId: chosen.id } }];

const blog = $json;
const blogs = JSON.parse(blog.blogsJson);
if (blogs.some((b) => b.slug === blog.slug)) throw new Error('Slug exists: ' + blog.slug);
if (blogs.some((b) => String(b.image || '').includes(blog.unsplashId))) throw new Error('Image used: ' + blog.unsplashId);

const post = {
  id: blog.nextId,
  slug: blog.slug,
  title: blog.title,
  excerpt: blog.excerpt,
  content: blog.content,
  image: blog.image,
  author: blog.author,
  date: blog.date,
  category: blog.category,
  tags: blog.tags,
  primaryKeyword: blog.primaryKeyword,
  secondaryKeywords: blog.secondaryKeywords,
};

blogs.push(post);
const body = JSON.stringify(blogs, null, 2) + '\n';

return [{
  json: {
    sha: blog.sha,
    content: Buffer.from(body, 'utf8').toString('base64'),
    message: `content: add blog ${post.slug} [${blog.primaryKeyword}]`,
    slug: post.slug,
    title: post.title,
    primaryKeyword: blog.primaryKeyword,
    keywordModel: blog.keywordModel,
    blogModel: blog.blogModel,
    wordCount: blog.wordCount,
    path: `/blogs/${post.slug}`,
  }
}];
